15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
23	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.rest.function.owner.CityLocality.of(owner.getCity()))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /** Membership tier: 'GOLD' when the owner's household has 3+ members (householdCount);
30	     *  otherwise 'SILVER' when the owner has no namesakes (namesakeCount 0) and an email is
31	     *  present, otherwise 'BRONZE'. */
32	    default String membershipTier(Owner owner) {
33	        if (owner.getHouseholdCount() != null && owner.getHouseholdCount() >= 3) {
34	            return "GOLD";
35	        }
36	        boolean unique = Integer.valueOf(0).equals(owner.getNamesakeCount());
37	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
38	        return unique && hasEmail ? "SILVER" : "BRONZE";
39	    }
40	
41	    /** Membership number: '<customerCode>-M<YY>', YY being the last two digits of the
42	     *  registrationDate year. Null until both source fields are assigned. */
43	    default String membershipNumber(Owner owner) {
44	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
45	            return null;
46	        }
47	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
48	    }
49	
50	    /** Stable identifier for the household an owner belongs to: same last name and address (normalized
51	     *  as in the duplicate-household guard) yield the same id, so household-sharing owners match. */
52	    default String householdId(Owner owner) {
53	        String key = normalizeHousehold(owner.getLastName()) + "|"
54	                + org.springframework.samples.petclinic.rest.function.owner.AddressNormalizer.normalize(owner.getAddress());
55	        return String.format("H-%08X", key.hashCode());
56	    }
57	
58	    private static String normalizeHousehold(String value) {
59	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
60	    }
61	
62	    Owner toOwner(OwnerDto ownerDto);
63	
64	    @Mapping(target = "id", ignore = true)
65	    @Mapping(target = "pets", ignore = true)
66	    Owner toOwner(OwnerFieldsDto ownerDto);
67	
68	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
69	
70	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
71	
72	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
73	        OwnerPageDto ownerPageDto = new OwnerPageDto();
74	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
75	        ownerPageDto.setPage(ownerPage.getNumber());
76	        ownerPageDto.setSize(ownerPage.getSize());
77	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
78	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
79	        return ownerPageDto;
80	    }
81	}
