2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many owners belong to this owner's household (same last name and
9	 * address, normalized as in the duplicate-household guard) after this create, i.e.
10	 * the existing members plus the new owner. Drives the 'GOLD' membership tier.
11	 */
12	public class CountHousehold {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String lastName = normalize(owner.getLastName());
16	        String address = AddressNormalizer.normalize(owner.getAddress());
17	        long existing = ownerRepository.findAll().stream()
18	                .filter(other -> lastName.equals(normalize(other.getLastName()))
19	                        && address.equals(AddressNormalizer.normalize(other.getAddress())))
20	                .count();
21	        owner.setHouseholdCount((int) existing + 1);
22	    }
23	
24	    private static String normalize(String value) {
25	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
26	    }
27	}
