    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.rest.function.owner.CityLocality.of(owner.getCity()))")
    OwnerDto toOwnerDto(Owner owner);

    /** Membership tier: 'GOLD' when the owner's household has 3+ members (householdCount);
     *  otherwise 'SILVER' when the owner has no namesakes (namesakeCount 0) and an email is
     *  present, otherwise 'BRONZE'. */
    default String membershipTier(Owner owner) {
        if (owner.getHouseholdCount() != null && owner.getHouseholdCount() >= 3) {
            return "GOLD";
        }
        boolean unique = Integer.valueOf(0).equals(owner.getNamesakeCount());
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        return unique && hasEmail ? "SILVER" : "BRONZE";
    }

    /** Membership number: '<customerCode>-M<YY>', YY being the last two digits of the
     *  registrationDate year. Null until both source fields are assigned. */
    default String membershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
    }

    /** Stable identifier for the household an owner belongs to: same last name and address (normalized
     *  as in the duplicate-household guard) yield the same id, so household-sharing owners match. */
    default String householdId(Owner owner) {
        String key = normalizeHousehold(owner.getLastName()) + "|"
                + org.springframework.samples.petclinic.rest.function.owner.AddressNormalizer.normalize(owner.getAddress());
        return String.format("H-%08X", key.hashCode());
    }

    private static String normalizeHousehold(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;
import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        LocalDate today = BusinessDay.roll(LocalDate.now());
        long createdToday = ownerRepository.findAll().stream()
                .filter(other -> today.equals(other.getRegistrationDate())).count();
        dto.setBulkSignupWarning(createdToday > 80);
        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}

